-- ============================================================
-- OKAYLIGHT LED 参数筛选器 - Supabase 数据库初始化脚本
-- ============================================================
-- 项目：OKAYLIGHT LED 参数筛选器
-- 说明：创建分类表、产品表，启用 RLS 策略，并插入初始数据
-- 日期：2026-07-25
-- ============================================================

-- ------------------------------------------------------------
-- 1. 创建表结构
-- ------------------------------------------------------------

-- 分类表
CREATE TABLE IF NOT EXISTS categories (
    id TEXT PRIMARY KEY,
    name TEXT,
    sort_order INT,
    config JSONB
);

-- 产品表
CREATE TABLE IF NOT EXISTS products (
    id BIGSERIAL PRIMARY KEY,
    category TEXT REFERENCES categories(id),
    kind TEXT,
    model TEXT,
    manufacturer TEXT,
    spec_data JSONB,
    price TEXT,
    datasheet_url TEXT,
    image_url TEXT,
    remarks TEXT,
    sort_order INT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- ------------------------------------------------------------
-- 2. 创建索引
-- ------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);
CREATE INDEX IF NOT EXISTS idx_products_model ON products(model);

-- ------------------------------------------------------------
-- 3. 启用行级安全策略 (RLS)
-- ------------------------------------------------------------

ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;

-- ------------------------------------------------------------
-- 4. RLS 策略（公开读写）
-- ------------------------------------------------------------

-- 分类表：允许公开读写
DROP POLICY IF EXISTS "Public read access on categories" ON categories;
CREATE POLICY "Public read access on categories"
    ON categories FOR SELECT
    USING (true);

DROP POLICY IF EXISTS "Public write access on categories" ON categories;
CREATE POLICY "Public write access on categories"
    ON categories FOR ALL
    USING (true)
    WITH CHECK (true);

-- 产品表：允许公开读写
DROP POLICY IF EXISTS "Public read access on products" ON products;
CREATE POLICY "Public read access on products"
    ON products FOR SELECT
    USING (true);

DROP POLICY IF EXISTS "Public write access on products" ON products;
CREATE POLICY "Public write access on products"
    ON products FOR ALL
    USING (true)
    WITH CHECK (true);

